def numberWays(hats: list[list[int]]) -> int:
    MOD = 10**9 + 7
    n = len(hats)
    hat_to_people = [[] for _ in range(41)]
    for person, preferred in enumerate(hats):
        for h in preferred:
            hat_to_people[h].append(person)
    memo = {}
    def dp(hat_id, mask):
        if mask == (1 << n) - 1: return 1
        if hat_id > 40: return 0
        state = (hat_id, mask)
        if state in memo: return memo[state]
        res = dp(hat_id + 1, mask)
        for person in hat_to_people[hat_id]:
            if not (mask & (1 << person)):
                res = (res + dp(hat_id + 1, mask | (1 << person))) % MOD
        memo[state] = res
        return res
    return dp(1, 0)

